SELECT

FROM t_comment
WHERE post_id = #{postId}
AND level = 1
AND status = 1

    AND floor > #{cursorFloor}

ORDER BY floor
LIMIT #{size}

SELECT id, post_id, user_id, root_id, parent_id, reply_user_id, level, content, floor, like_count, reply_count, is_author, status, create_time FROM ( SELECT , ROW_NUMBER() OVER (PARTITION BY root_id ORDER BY create_time, id) AS rn FROM t_comment WHERE root_id IN
#{rootId}
AND status = 1 ) t WHERE t.rn <= #{limit} ORDER BY t.root_id, t.rn

mapper.update:
UPDATE t_comment
SET reply_count = GREATEST(0, CAST(reply_count AS SIGNED) + #{delta})
WHERE id = #{rootId}

UPDATE t_comment
SET status = 3
WHERE id = #{id}

UPDATE t_comment
SET like_count = GREATEST(0, CAST(like_count AS SIGNED) + CASE id

    WHEN #{d.targetId} THEN #{d.delta}

ELSE 0 END)
WHERE id IN

    #{d.targetId}
